_sage_const_0 = Integer(0); _sage_const_1 = Integer(1); _sage_const_2 = Integer(2); _sage_const_3 = Integer(3); _sage_const_4 = Integer(4); _sage_const_8 = Integer(8); _sage_const_9 = Integer(9); _sage_const_7 = Integer(7); _sage_const_6 = Integer(6); _sage_const_5 = Integer(5)
def involutions(n):
    invs = []
    for p in Permutations(n):
        if p.inverse() == p:
            invs.append(p)
    return invs

def graphs_per_outcome_count(out):
    # Initialization adjusted to not have to consider car 1
    n = len(out)
    street = [_sage_const_0 ]*n
    street[_sage_const_0 ] = _sage_const_1 
    queue = sorted(list(zip(out, list(range(n)))))[_sage_const_1 :]
    claws = []

    for car, pos in queue:
        old_pos = pos
        street[pos] = car
        # Looking for first Fibonacci start (incomprehensible :C)
        if pos == _sage_const_1  or (pos == _sage_const_2  and street[_sage_const_1 ] == _sage_const_0 ):
            continue
        if street[pos-_sage_const_1 ] >= _sage_const_2  and street[pos-_sage_const_2 ] == _sage_const_0 :
            pos -= _sage_const_1 
        if street[pos-_sage_const_1 ] == _sage_const_0  and street[pos-_sage_const_2 ] != _sage_const_1 :
            # go 3 back if there is a car there, go 4 back if there isn't
            pos -= (_sage_const_3  + int(street[pos-_sage_const_3 ] == _sage_const_0 )) 
        else:
            pos -= _sage_const_2 

        fib = _sage_const_0 
        gap = False
        for i in range(pos, -_sage_const_1 , -_sage_const_1 ):
            if not gap: # and street[i] != 0 (redundant)
                fib += _sage_const_1 
                gap = True
            elif gap and street[i] == _sage_const_0 :
                gap = False
            elif gap and street[i] != _sage_const_0 :
                claws.append(fibonacci(fib + _sage_const_2 ))
                fib = _sage_const_1 
                gap = True
        claws.append(fibonacci(fib + _sage_const_2 ))
        cars_behind = sum([int(street[i] < car) for i in range(old_pos+_sage_const_1 , n)])
        claws.append(_sage_const_2 **cars_behind)
    return prod(claws)

